{ title = "Stage 1: At Torwa take Lar'korwi's chain. Complete the fixed carcass, t", note = "At Torwa take Lar'korwi's chain. Complete the fixed carcass, then two scent glands per person and the named finale. The glands are a declared small collection exception, not guaranteed drops.", goals = {{t = "task", text = "Confirm stage 1 complete with all five players"}} },
