{ title = "Stage 3: Collect Crystals of Power4284, Expedition Salvation3881, Alien", note = "Collect Crystals of Power4284, Expedition Salvation3881, Alien Ecology3883, Larion and Muigin4145, Beware of Pterrordax4501 and the ape chain at the appropriate hubs.", goals = {{t = "task", text = "Confirm stage 3 complete with all five players"}} },
{ title = "Quest reward: Crystals of Power", note = "Crystals of Power Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge. Red Power Crystal ( 7 ) Yellow Power Crystal ( 7 ) Green Power Crystal ( 7 ) Blue Power Crystal ( 7 ) ", goals = {{t = "task", text = "Confirm Crystals of Power (4284) turned in, or already completed."}} },
{ title = "Quest reward: Expedition Salvation", note = "Expedition Salvation Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater . Crate of Foodstuffs ( 1 ) Research Equipment ( 1 ) ", goals = {{t = "task", text = "Confirm Expedition Salvation (3881) turned in, or already completed."}} },
{ title = "Quest reward: Alien Ecology", note = "Alien Ecology Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater . Look for the chambers with the hanging larval spawns. Bring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater . Hive Wall Sample ( 1 ) Provided item: Unused Scraping Vial ( 1 ) ", goals = {{t = "task", text = "Confirm Alien Ecology (3883) turned in, or already completed."}} },
{ title = "Quest reward: Larion and Muigin", note = "Larion and Muigin Hunt 5 Bloodpetal Lashers , 5 Bloodpetal Threshers , 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge. Bloodpetal Lasher slain ( 5 ) Bloodpetal Trapper slain ( 5 ) Bloodpetal Flayer slain ( 5 ) Bloodpetal Thresher slain ( 5 ) ", goals = {{t = "task", text = "Confirm Larion and Muigin (4145) turned in, or already completed."}} },
