{ title = "Quest reward: The Mighty U'cha", note = "The Mighty U'cha Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater . U'cha's Pelt ( 1 ) ", goals = {{t = "task", text = "Confirm The Mighty U'cha (4301) turned in, or already completed."}} },
{ title = "Stage 8: Finish all local hand-ins. Roll the Bones, random Crystal Infu", note = "Finish all local hand-ins. Roll the Bones, random Crystal Infused Scale and Mangled Journal drops are bonuses, not baseline rewards. The New Springs is carried only if a later Winterspring visit is actually selected.", goals = {{t = "task", text = "Confirm stage 8 complete with all five players"}} },
{ title = "Quest reward: The Fare of Lar'korwi", note = "The Fare of Lar'korwi Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater . Piece of Threshadon Carcass ( 1 ) ", goals = {{t = "task", text = "Confirm The Fare of Lar'korwi (4290) turned in, or already completed."}} },
