{ title = "Quest reward: The Bait for Lar'korwi", note = "The Bait for Lar'korwi Using the contents of Torwa's Pouch , summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater . Lar'korwi's Head ( 1 ) Provided item: Torwa's Pouch ( 1 ) ", goals = {{t = "task", text = "Confirm The Bait for Lar'korwi (4292) turned in, or already completed."}} },
