{ title = "Quest reward: The Apes of Un'Goro", note = "The Apes of Un'Goro Bring 2 Un'Goro Gorilla Pelts , 2 Un'Goro Stomper Pelts , and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater . Un'Goro Gorilla Pelt ( 2 ) Un'Goro Stomper Pelt ( 2 ) Un'Goro Thunderer Pelt ( 2 ) ", goals = {{t = "task", text = "Confirm The Apes of Un'Goro (4289) turned in, or already completed."}} },
